def compute_score(data_source, solution_str, ground_truth, extra_info=None, **kwargs):
    if solution_str is None:
        return 0.0
    # The held-out grader is strict: it only reads the number inside the LAST
    # ``\boxed{...}``. Math-Verify, by contrast, extracts *any* math expression
    # in the text (ExprExtractionConfig), so a response that was truncated at
    # max_response_length before ever emitting ``\boxed{...}`` — but that ends
    # with the gold number in its final visible expression — is scored 1.0.
    # That rewards exactly the degenerate "keep going until you happen to
    # state the answer, then get cut off" behavior the strict grader scores 0.
    # Gate on a fully-formed ``\boxed{...}`` so training reward matches the
    # held-out rule.
    idx = solution_str.rfind("\\boxed")
    if idx < 0:
        return 0.0
    open_brace = solution_str.find("{", idx)
    if open_brace < 0:
        return 0.0
    depth = 0
    closed = False
    for ch in solution_str[open_brace:]:
        if ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                closed = True
                break
    if not closed:
        return 0.0
    return float(math_verify.compute_score(solution_str, str(ground_truth)))

